package org.telegram.ui;
import android.content.Context;import android.view.Gravity;import android.view.View;import android.widget.FrameLayout;
import org.telegram.messenger.DevGramPlugins;import org.telegram.messenger.R;import org.telegram.ui.ActionBar.ActionBar;import org.telegram.ui.ActionBar.BaseFragment;import org.telegram.ui.ActionBar.Theme;import org.telegram.ui.Components.LayoutHelper;import org.telegram.ui.Components.UItem;import org.telegram.ui.Components.UniversalAdapter;import org.telegram.ui.Components.UniversalRecyclerView;import java.util.ArrayList;
public class DevGramMySubmissionsActivity extends BaseFragment{
 private final ArrayList<DevGramPlugins.CatalogEntry> rows=new ArrayList<>(); private UniversalRecyclerView list;
 @Override public View createView(Context c){actionBar.setBackButtonImage(R.drawable.ic_ab_back);actionBar.setTitle("Мои заявки");actionBar.setActionBarMenuOnItemClick(new ActionBar.ActionBarMenuOnItemClick(){@Override public void onItemClick(int id){if(id==-1)finishFragment();}});FrameLayout root=new FrameLayout(c);list=new UniversalRecyclerView(this,this::fill,null,null);list.setBackgroundColor(Theme.getColor(Theme.key_windowBackgroundGray,resourceProvider));root.addView(list,LayoutHelper.createFrame(-1,-1,Gravity.FILL));DevGramPlugins.fetchMySubmissions(x->{rows.clear();rows.addAll(x);list.adapter.update(true);});return fragmentView=root;}
 private void fill(ArrayList<UItem> items,UniversalAdapter a){items.add(UItem.asHeader("Заявки и публикации"));if(rows.isEmpty()){items.add(UItem.asShadow("Заявок пока нет."));return;}for(DevGramPlugins.CatalogEntry e:rows){String state="published".equals(e.submissionState)?"Опубликован":"pending".equals(e.submissionState)?"На модерации":"Отклонено: "+e.rejectionReason;items.add(UItem.asButton(e.hashCode(),R.drawable.msg_info,e.name+"  v"+e.version,state));}items.add(UItem.asShadow(null));}
}
